 15	public final class RelationIdentifier {
 16	
 17	    public static final String TOSTRING_DELIMITER = "-";
 18	
 19	    private final long outVertexId;
 20	    private final long typeId;
 21	    private final long relationId;
 22	
 23	    private RelationIdentifier(final long outVertexId, final long typeId, final long relationId) {
 24	        this.outVertexId = outVertexId;
 25	        this.typeId = typeId;
 26	        this.relationId = relationId;
 27	    }
 28	
 29	    static final RelationIdentifier get(InternalRelation r) {
 30	        if (r.hasId()) {
 31	            return new RelationIdentifier(r.getVertex(0).getID(),
 32	                    r.getType().getID(),
 33	                    r.getID());
 34	        } else return null;
 35	    }
 36	
 37	    static final RelationIdentifier get(TitanProperty property) {
 38	        if (property.hasId()) {
 39	            return new RelationIdentifier(property.getVertex().getID(),
 40	                    property.getPropertyKey().getID(),
 41	                    property.getID());
 42	        } else return null;
 43	    }
 44	
 45	    static final RelationIdentifier get(TitanVertex startVertex, TitanType type, long relationId) {
 46	        if (AbstractVertex.isTemporaryId(relationId)) return null;
 47	        else return new RelationIdentifier(startVertex.getID(),type.getID(),relationId);
 48	    }
 49	
 50	    static final RelationIdentifier get(TitanEdge edge) {
 51	        if (edge.hasId()) {
 52	            return new RelationIdentifier(edge.getVertex(Direction.OUT).getID(),
 53	                    edge.getTitanLabel().getID(),
 54	                    edge.getID());
 55	        } else return null;
 56	    }
 57	
 58	    public long[] getLongRepresentation() {
 59	        long[] r = new long[3];
 60	        r[0]=outVertexId;
 61	        r[1]=typeId;
 62	        r[2]=relationId;
 63	        return r;
 64	    }
 65	
 66	    @Override
 67	    public int hashCode() {
 68	        return Long.valueOf(relationId).hashCode() +
 69	                Long.valueOf(outVertexId).hashCode() * 743 +
 70	                Long.valueOf(typeId).hashCode() * 3011;
 71	    }
 72	
 73	    @Override
 74	    public boolean equals(Object other) {
 75	        if (this == other) return true;
 76	        else if (!getClass().isInstance(other)) return false;
 77	        RelationIdentifier oth = (RelationIdentifier) other;
 78	        return relationId == oth.relationId && outVertexId == oth.outVertexId && typeId == oth.typeId;
 79	    }
 80	
 81	    @Override
 82	    public String toString() {
 83	        StringBuilder s = new StringBuilder();
 84	        s.append(LongEncoding.encode(relationId)).append(TOSTRING_DELIMITER).append(LongEncoding.encode(outVertexId))
 85	                .append(TOSTRING_DELIMITER).append(LongEncoding.encode(typeId));
 86	        return s.toString();
 87	    }
