 89	    TitanRelation findRelation(TitanTransaction tx) {
 90	        TitanVertex v = tx.getVertex(outVertexId);
 91	        if (v == null) return null;
 92	        TitanVertex type = tx.getVertex(typeId);
 93	        if (type == null) return null;
 94	        if (!(type instanceof TitanType))
 95	            throw new IllegalArgumentException("Invalid RelationIdentifier: typeID does not reference a type");
 96	        for (TitanRelation r : v.query().types((TitanType)type).direction(Direction.OUT).relations()) {
 97	            //Find current or previous relation
 98	            if (r.getID() == relationId ||
 99	                    ((r instanceof StandardRelation) && ((StandardRelation)r).getPreviousID()==relationId)) return r;
100	        }
101	        return null;
102	    }
103	
104	    public TitanEdge findEdge(TitanTransaction tx) {
105	        TitanRelation r = findRelation(tx);
106	        if (r==null) return null;
107	        else if (r instanceof TitanEdge) return (TitanEdge)r;
108	        else throw new UnsupportedOperationException("Referenced relation is a property not an edge");
109	    }
110	
111	    public TitanProperty findProperty(TitanTransaction tx) {
112	        TitanRelation r = findRelation(tx);
113	        if (r==null) return null;
114	        else if (r instanceof TitanProperty) return (TitanProperty)r;
115	        else throw new UnsupportedOperationException("Referenced relation is a edge not a property");
116	    }
117	
118	    public static final RelationIdentifier parse(String id) {
119	        String[] elements = id.split(TOSTRING_DELIMITER);
120	        if (elements.length != 3) throw new IllegalArgumentException("Not a valid relation identifier: " + id);
121	        try {
122	            return new RelationIdentifier(LongEncoding.decode(elements[1]),
123	                    LongEncoding.decode(elements[2]),
124	                    LongEncoding.decode(elements[0]));
125	        } catch (NumberFormatException e) {
126	            throw new IllegalArgumentException("Invalid id - each token expected to be a number",e);
127	        }
128	    }
129	
