131	        if (ids.length != 3) throw new IllegalArgumentException("Not a valid relation identifier: " + Arrays.toString(ids));
132	        for (int i = 0; i < 3; i++) {
133	            if (ids[i] < 0)  throw new IllegalArgumentException("Not a valid relation identifier: " + Arrays.toString(ids));
134	        }
135	        return new RelationIdentifier(ids[0], ids[1], ids[2]);
136	    }
